// One form submission per item. Field names match the labels in the form: Name, Email, Message.
const m = $input.item.json;
const name = String(m['Name'] || '').trim();
const email = String(m['Email'] || '').trim();
const message = String(m['Message'] || '').trim();

// Plain checks first. These do not need a model and catch the laziest spam.
const linkCount = (message.match(/(https?:\/\/|www\.)/gi) || []).length;
const maxLinks = Number(m.max_links);
const hardReasons = [];
if (/(https?:\/\/|www\.)/i.test(name)) hardReasons.push('the name field contains a link');
if (Number.isFinite(maxLinks) && linkCount > maxLinks) hardReasons.push(`${linkCount} links in the message (limit ${maxLinks})`);

const phrases = String(m.spam_phrases || '').split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const phraseHits = phrases.filter((p) => message.toLowerCase().includes(p));

const system = [
  `You screen messages sent through the contact form of this business: ${m.business_description || 'a small business'}.`,
  'Decide if a real person is writing to this business about something they want from it:',
  'a question, an order, a booking, a quote request, a complaint, or a reply to something the business sent.',
  'Spam is: unsolicited sales pitches (SEO, marketing, web design, app development, lead lists, funding),',
  'scams, link drops, adult or gambling content, and text that makes no sense.',
  'If you are unsure, choose genuine. A missed customer costs more than one spam email.',
  'Answer with JSON only, in this shape:',
  '{"verdict": "genuine", "reason": "one short sentence"}',
  'verdict must be "genuine" or "spam".',
].join('\n');

const user = [
  `NAME: ${name}`,
  `EMAIL: ${email}`,
  `LINKS IN MESSAGE: ${linkCount}`,
  phraseHits.length ? `WATCH-LIST PHRASES FOUND: ${phraseHits.join(', ')}` : 'WATCH-LIST PHRASES FOUND: none',
  '',
  'MESSAGE:',
  message.slice(0, 4000),
].join('\n');

return {
  json: {
    name, email, message,
    submitted_at: m.submittedAt || '',
    notify_email: m.notify_email || '',
    from_email: m.from_email || '',
    link_count: linkCount,
    phrase_hits: phraseHits,
    hard_spam_reasons: hardReasons,
    ollama_request: {
      url: String(m.ollama_url || 'http://localhost:11434').replace(/\/+$/, '') + '/api/chat',
      body: {
        model: m.ollama_model || 'qwen2.5:3b',
        stream: false,
        format: 'json',
        options: { temperature: 0 },
        messages: [
          { role: 'system', content: system },
          { role: 'user', content: user },
        ],
      },
    },
  },
};

// Ollama's /api/chat answer is in message.content. With format: "json" it should be a JSON string,
// but a small model sometimes wraps it in text, so take the first {...} block if a plain parse fails.
function readModelJson(res) {
  const raw = String((res && res.message && res.message.content) || res.response || '').trim();
  if (!raw) return { ok: false, raw, data: {} };
  try { return { ok: true, raw, data: JSON.parse(raw) }; } catch (e) {}
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { return { ok: true, raw, data: JSON.parse(m[0]) }; } catch (e) {} }
  return { ok: false, raw, data: {} };
}

const f = $('Check Message And Build Prompt').item.json;
const parsed = readModelJson($input.item.json);
const modelVerdict = String(parsed.data.verdict || '').toLowerCase().trim();
const modelReason = String(parsed.data.reason || '').trim();

let isSpam;
let decidedBy;
let reason;
if (f.hard_spam_reasons.length) {
  isSpam = true; decidedBy = 'rules'; reason = f.hard_spam_reasons.join('; ');
} else if (modelVerdict === 'spam') {
  isSpam = true; decidedBy = 'model'; reason = modelReason || 'the model called it spam';
} else if (modelVerdict === 'genuine') {
  isSpam = false; decidedBy = 'model'; reason = modelReason || 'the model called it genuine';
} else {
  // Unreadable answer: let it through, so a real customer is never lost to a model hiccup.
  isSpam = false; decidedBy = 'fallback'; reason = 'the model answer could not be read, so it was let through';
}

return {
  json: {
    is_spam: isSpam,
    decided_by: decidedBy,
    reason,
    name: f.name,
    email: f.email,
    message: f.message,
    submitted_at: f.submitted_at,
    notify_email: f.notify_email,
    from_email: f.from_email,
    link_count: f.link_count,
    phrase_hits: f.phrase_hits,
  },
};

